import{_ as e,o,c as s,ag as t}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Car Wash","description":"","frontmatter":{},"headers":[],"relativePath":"pt/car-wash/index.md","filePath":"pt/car-wash/index.md"}'),r={name:"pt/car-wash/index.md"};function n(i,a,d,l,c,p){return o(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="car-wash" tabindex="-1">Car Wash <a class="header-anchor" href="#car-wash" aria-label="Permalink to &quot;Car Wash&quot;">​</a></h1><p>Entre de carro, escolha um programa, e o veículo passa por escovas rotativas, espuma, arcos de enxaguamento e um secador a vapor, enquanto todos à volta veem a mesma lavagem. A pé, os jogadores usam uma máquina de alta pressão e removem a sujidade nível a nível. Cada local é posicionado no jogo e cada definição é editada no jogo.</p><h2 id="funcionalidades" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades" aria-label="Permalink to &quot;Funcionalidades&quot;">​</a></h2><ul><li><strong>Túneis drive-thru</strong>: escovas ajustadas à largura do veículo, arcos de sabão e de enxaguamento, secador a vapor, sincronizados para todos os jogadores próximos. Consulte <a href="/pt/car-wash/tunnels">Túneis</a>.</li><li><strong>Programas de lavagem</strong>: nome, preço, velocidade e as etapas incluídas (sabão, enxaguamento, secagem, cera). A cera mantém o veículo limpo durante o tempo que escolher.</li><li><strong>Máquinas de alta pressão</strong> em qualquer prop do mundo que indicar, ou em estações que posiciona, pagas por nível de sujidade. Consulte <a href="/pt/car-wash/pressure-washers">Máquinas de alta pressão</a>.</li><li><strong>Editor de túneis no jogo</strong>: crie um túnel onde está ou copie uma lavagem do jogo base, mova cada peça com o teclado e guarde.</li><li><strong>Tudo no <code>/nay</code></strong>: preços, programas, descontos por profissão, conta de pagamento, classes de veículo bloqueadas, blips com seletor visual de ícone e de cor. Consulte <a href="/pt/car-wash/settings">Definições</a>.</li><li><strong>Justo e seguro</strong>: um veículo por túnel, verificações de sentido contrário e de passagem bloqueada, pagamentos e reserva do túnel validados no servidor.</li><li><strong>Descontos por profissão</strong> e uma percentagem de preço por túnel. Os jogadores pagam em dinheiro, pelo banco, ou em dinheiro e depois pelo banco.</li><li><strong>Atento ao mapa</strong>: as escovas estáticas do mapa são escondidas ao longo de cada túnel e regressam quando o recurso para. Em Strawberry, os ficheiros de mapa sem escovas substituem a lavagem original.</li><li><strong>API HTTP e webhooks</strong>: histórico de lavagens e estatísticas para o seu site ou bot, uma mensagem no Discord a cada lavagem. Consulte <a href="/pt/car-wash/api">API e webhooks</a>.</li><li><strong>Seis idiomas</strong>: inglês, francês, espanhol, português, polaco, alemão.</li></ul><h2 id="compatibilidade" tabindex="-1">Compatibilidade <a class="header-anchor" href="#compatibilidade" aria-label="Permalink to &quot;Compatibilidade&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detetados automaticamente.</li><li>Target (opcional, para as máquinas de alta pressão): ox_target ou qb-target. Sem nenhum deles, os jogadores usam um aviso de tecla.</li><li>Dependências: oxmysql e <code>nay_lib</code> (incluído na sua compra).</li></ul><h2 id="desempenho" tabindex="-1">Desempenho <a class="header-anchor" href="#desempenho" aria-label="Permalink to &quot;Desempenho&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Estado</th><th>Cliente (resmon)</th></tr></thead><tbody><tr><td>Em repouso</td><td>0,00 ms</td></tr><tr><td>A lavar um veículo</td><td>cerca de 0,08 ms</td></tr></tbody></table><p>Medido com o resmon na game build 3751.</p><h2 id="instalacao" tabindex="-1">Instalação <a class="header-anchor" href="#instalacao" aria-label="Permalink to &quot;Instalação&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p>Guia completo na página <a href="/pt/getting-started">Primeiros passos</a>. Depois atribua a si próprio <code>nay_car_wash.config</code> (ou <code>nay.admin</code>) e abra o <code>/nay</code>. Dois túneis vêm prontos a usar: Strawberry e Little Seoul.</p>`,12)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
